// Pega o CSV bruto como texto vindo do nó anterior
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

// Quebra as linhas e remove vazias
const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
if (lines.length === 0) return [{ json: { investimentos: [] } }];

// Função auxiliar para parsear CSV respeitando aspas (vírgulas dentro de campos)
const parseCSVLine = (line) => {
  const result = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === ',' && !inQuotes) {
      result.push(current.trim());
      current = '';
    } else {
      current += char;
    }
  }
  result.push(current.trim());
  return result.map(val => val.replace(/^"|"$/g, '')); // Remove aspas nas pontas
};

// Extrai os cabeçalhos
const headers = parseCSVLine(lines[0]);

// Processa as linhas de dados
const investimentos = lines.slice(1).map(line => {
  const cols = parseCSVLine(line);
  const obj = {};

  headers.forEach((h, i) => {
    obj[h] = cols[i] ?? "";
  });

  // Normaliza o campo 'minimo' para número de forma segura (suportando decimais com ponto ou vírgula)
  if (obj.minimo !== undefined) {
    let cleanVal = String(obj.minimo).replace(/\s/g, "").replace(",", ".");
    cleanVal = cleanVal.replace(/[^\d.]/g, "");
    obj.minimo = Number(cleanVal) || 0;
  }

  return obj;
});

return [{ json: { investimentos } }];

// Função auxiliar para converter o saldo em string ("R$ 28.900,00") para número puro (28900)
function parseSaldo(saldoStr) {
  if (typeof saldoStr === 'number') return saldoStr;
  if (!saldoStr) return 0;
  const cleanStr = String(saldoStr)
    .replace(/[^\d,-]/g, '') // Remove R$, espaços e pontos de milhar
    .replace(',', '.');       // Substitui vírgula decimal por ponto
  return parseFloat(cleanStr) || 0;
}

// 1. Recupera a lista de clientes (vinda do Webhook) e a lista de investimentos (vinda do CSV)
const mergedData = $input.all();

// No nó Merge, a entrada 0 geralmente traz os clientes e a entrada 1 os investimentos
// ou ambos vêm no mesmo item dependendo da configuração. Vamos extrair com segurança:
const clientes = mergedData[0]?.json?.clientes ?? mergedData[0]?.json?.body?.clientes ?? [];
const investimentos = mergedData[0]?.json?.investimentos ?? mergedData[1]?.json?.investimentos ?? [];

// Array para armazenar o resultado final formatado para envio
const resultados = [];

// 2. Itera sobre cada cliente para encontrar as melhores opções
for (const cliente of clientes) {
  const saldoNum = parseSaldo(cliente.saldo);

  // Filtra os investimentos compatíveis com o perfil do cliente e com o saldo mínimo
  const recomendacoes = investimentos.filter(inv => {
    const mesmoPerfil = inv.perfil?.toLowerCase() === cliente.perfil?.toLowerCase();
    const cabeNoBolso = inv.minimo <= saldoNum;
    return mesmoPerfil && cabeNoBolso;
  });

  // 3. Monta o corpo da mensagem / e-mail
  let textoInvestimentos = '';
  if (recomendacoes.length > 0) {
    textoInvestimentos = recomendacoes.map(inv => 
      `- ${inv.produto}: Aplicação mínima de R$ ${inv.minimo.toLocaleString('pt-BR', { minimumFractionDigits: 2 })} (Rentabilidade: ${inv.rentabilidade})`
    ).join('\n');
  } else {
    textoInvestimentos = '- No momento, não encontramos opções de investimento com o aporte mínimo disponível para o seu saldo atual.';
  }

  const mensagemEmail = `Olá, ${cliente.nome}!\n\n` +
    `Analisamos que o seu perfil de investidor é considerado '${cliente.perfil}' e o saldo disponível em sua conta é de ${cliente.saldo}.\n\n` +
    `Com base nas suas características, selecionamos as seguintes opções de investimento recomendadas para você:\n\n` +
    `${textoInvestimentos}\n\n` +
    `Se você tiver alguma dúvida, nossa equipe está à disposição para ajudar!\n\n` +
    `Atenciosamente,\n` +
    `Equipe de Investimentos DIO`;

  resultados.push({
    json: {
      cliente: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      saldoNumerico: saldoNum,
      qtdOpcoesEncontradas: recomendacoes.length,
      opcoesInvestimento: recomendacoes,
      assuntoEmail: `Sugestão de Investimentos para o seu perfil ${cliente.perfil}`,
      corpoEmail: mensagemEmail
    }
  });
}

return resultados;

// Obtém todos os itens que chegam do nó anterior no n8n
const items = $input.all();

let resultados = [];

if (items.length > 0) {
  const firstJson = items[0].json;
  if (firstJson.resultados && Array.isArray(firstJson.resultados)) {
    resultados = firstJson.resultados;
  } else if (Array.isArray(firstJson)) {
    resultados = firstJson;
  } else {
    resultados = items.map(item => item.json);
  }
}

// Processa e normaliza mapeando exatamente os nomes que o nó anterior envia
const out = resultados.map(c => {
  const nomeCliente = c.cliente || c.nome || "Cliente";
  const emailCliente = c.email || c.email_to || "";
  const perfilCliente = c.perfil || "Não informado";
  const saldoTexto = c.saldo || "R$ 0,00";
  const saldoNum = c.saldoNumerico !== undefined ? Number(c.saldoNumerico) : 0;

  // Monta a recomendação com base nas opções encontradas ou no corpo do email
  let recomendacaoStr = "";
  if (Array.isArray(c.opcoesInvestimento) && c.opcoesInvestimento.length > 0) {
    recomendacaoStr = c.opcoesInvestimento.map(inv => `${inv.produto} (${inv.rentabilidade})`).join(", ");
  } else {
    recomendacaoStr = "Sem opções compatíveis no momento";
  }

  const mensagemBase = c.corpoEmail || c.mensagem_base || `Olá, ${nomeCliente}! Analisamos seu perfil ${perfilCliente}.`;

  return {
    json: {
      email_to: String(emailCliente).trim().toLowerCase(),
      nome: String(nomeCliente).trim(),
      perfil: perfilCliente,
      saldo_texto: saldoTexto,
      saldo_num: saldoNum,
      recomendacao: recomendacaoStr,
      motivo: `Perfil compatível com saldo de ${saldoTexto}`,
      mensagem_base: String(mensagemBase).trim(),
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

const items = $input.all();

return items.map(item => {
  return {
    json: {
      prompt_cliente: `Cliente: ${item.json.nome || item.json.cliente || ''}\n\nMensagem base:\n${item.json.mensagem_base || item.json.mensagemBase || ''}`
    }
  };
});

// Pega os resultados processados pelo AI Agent na entrada atual
const aiOutputs = $input.all();

// Pega os dados originais dos clientes do nó de processamento anterior
const originalClients = $('Recomendação').all();

return aiOutputs.map((item, index) => {
  const originalData = originalClients[index]?.json || {};
  const textoIA = item.json.output || '';

  // Extrai a primeira linha (saudação) para pegar o nome ou usa o original
  const emailTo = originalData.email_to || originalData.email || '';
  const nomeCliente = originalData.nome || originalData.cliente || 'Cliente';
  const perfil = originalData.perfil || '';

  // Define um assunto personalizado para o e-mail
  const assunto = `Sugestão de Investimentos - Perfil ${perfil || 'Personalizado'}`;

  // Converte o Markdown leve da IA (**bold**) para tags HTML ou limpa para texto puro
  const corpoEmailHtml = textoIA
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/\n/g, '<br>');

  return {
    json: {
      email_to: emailTo,
      subject: assunto,
      cliente_nome: nomeCliente,
      perfil: perfil,
      mensagem_raw: textoIA,
      mensagem_html: corpoEmailHtml
    }
  };
});
